CREATE TABLE IF NOT EXISTS "ecommerce"."role" ("id" SERIAL NOT NULL, "name" character varying(256) NOT NULL, "description" character varying(512), "type" integer NOT NULL, "created_by" character varying NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_by" character varying, "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "deleted_by" character varying, CONSTRAINT "pk_role" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "ecommerce"."user_role" ("user_id" uuid NOT NULL, "role_id" integer NOT NULL, CONSTRAINT "PK_f634684acb47c1a158b83af5150" PRIMARY KEY ("user_id", "role_id"));
CREATE TABLE IF NOT EXISTS "ecommerce"."user" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "department_id" bigint NOT NULL, "first_name" character varying(50) NOT NULL, "last_name" character varying(50) NOT NULL, "user_name" character varying(15) NOT NULL, "email" character varying(50) NOT NULL, "password" character varying NOT NULL, "status" integer NOT NULL, "is_system_user" boolean NOT NULL DEFAULT false, "is_confirmed" boolean NOT NULL DEFAULT false, "provider" integer NOT NULL, CONSTRAINT "UQ_d34106f8ec1ebaf66f4f8609dd6" UNIQUE ("user_name"), CONSTRAINT "UQ_e12875dfb3b1d92d7d7c5377e22" UNIQUE ("email"), "created_by" character varying NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_by" character varying, "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "deleted_by" character varying, CONSTRAINT "pk_user" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "ecommerce"."department" ("id" BIGSERIAL NOT NULL, "name" character varying(100) NOT NULL, "created_by" character varying NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_by" character varying, "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "deleted_by" character varying, CONSTRAINT "pk_department" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "ecommerce"."role_permission" ("role_id" integer NOT NULL, "permission_id" uuid NOT NULL, CONSTRAINT "PK_19a94c31d4960ded0dcd0397759" PRIMARY KEY ("role_id", "permission_id"));
CREATE TABLE IF NOT EXISTS "ecommerce"."user_permission" ("user_id" uuid NOT NULL, "permission_id" uuid NOT NULL, CONSTRAINT "PK_e55fe6295b438912cb42bce1baa" PRIMARY KEY ("user_id", "permission_id"));
CREATE TABLE IF NOT EXISTS "ecommerce"."permission" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "menu_id" uuid NOT NULL, "name" character varying(256) NOT NULL, "description" character varying(512), "key" character varying(256) NOT NULL, "type" integer NOT NULL, CONSTRAINT "UQ_20ff45fefbd3a7c04d2572c3bbd" UNIQUE ("key"), "created_by" character varying NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_by" character varying, "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "deleted_by" character varying, CONSTRAINT "pk_permission" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "ecommerce"."menu" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "name" character varying(256) NOT NULL, "description" character varying(512), "key" character varying(256) NOT NULL, "parent_id" uuid, "order_no" integer NOT NULL, "is_active" boolean NOT NULL DEFAULT false, "link" character varying(256), "created_by" character varying NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_by" character varying, "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "deleted_by" character varying, CONSTRAINT "pk_menu" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "communication"."notification_setting" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "name" character varying(255), "description" character varying(255), "type" integer NOT NULL, "is_urgent" boolean NOT NULL, "created_by" character varying NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_by" character varying, "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "deleted_by" character varying, CONSTRAINT "pk_notification_setting" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "communication"."notification_template" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "type" character varying(255), "code" character varying(255), "description" character varying(500), "notification_setting_id" uuid NOT NULL, "email_sender" character varying(255), "subject" jsonb, "list_of_recipient_types" character varying(255), "content" jsonb, "is_latest_version" boolean NOT NULL DEFAULT true, "created_by" character varying NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_by" character varying, "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "deleted_by" character varying, CONSTRAINT "pk_notification_template" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "communication"."notification" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "recipient_id" uuid NOT NULL, "template_id" uuid NOT NULL, "message" character varying(3000), "link" character varying(500), "sending_time" TIMESTAMP WITH TIME ZONE NOT NULL, "succeed_sending_time" TIMESTAMP WITH TIME ZONE NOT NULL, "is_read" boolean NOT NULL DEFAULT false, "read_at" TIMESTAMP WITH TIME ZONE, "action_data" jsonb, "created_by" character varying NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_by" character varying, "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "deleted_by" character varying, CONSTRAINT "pk_notification" PRIMARY KEY ("id"));
